def test_benchmark_gpu_wp_funcs_uses_fake_warp_backend(
    benchmark_module,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """GPU wp.func benchmark helper can run against a fake Warp facade."""
    launch_calls: list[tuple[object, int, str]] = []

    class _FakeWarp:
        float64 = np.float64

        @staticmethod
        def array(values, dtype=None, device=None):
            return np.asarray(values, dtype=np.float64)

        @staticmethod
        def zeros(shape, dtype=None, device=None):
            return np.zeros(shape, dtype=np.float64)

        @staticmethod
        def launch(kernel, dim, inputs=None, outputs=None, device=None):
            launch_calls.append((kernel, dim, device))

        @staticmethod
        def synchronize():
            return None

    monkeypatch.setattr(benchmark_module, "wp", _FakeWarp())
    monkeypatch.setattr(
        benchmark_module,
        "_diffusion_coefficient_kernel",
        object(),
        raising=False,
    )
    monkeypatch.setattr(
        benchmark_module,
        "_mass_transfer_rate_kernel",
        object(),
        raising=False,
    )
    monkeypatch.setattr(
        benchmark_module,
        "_particle_radius_kernel",
        object(),
        raising=False,
    )
    monkeypatch.setattr(
        benchmark_module,
        "_brownian_diffusivity_kernel",
        object(),
        raising=False,
    )
    monkeypatch.setattr(
        benchmark_module,
        "_brownian_kernel_pair_kernel",
        object(),
        raising=False,
    )

    result = benchmark_module._benchmark_gpu_wp_funcs(
        benchmark_module._build_wp_func_benchmark_inputs(4, seed=11)
    )

    assert len(launch_calls) == 10
    assert set(result) == {
        "diffusion_coefficient",
        "mass_transfer_rate",
        "particle_radius_from_volume",
        "brownian_diffusivity",
        "brownian_kernel_pair",
    }
    assert all(value >= 0.0 for value in result.values())

def test_profile_row_keeps_host_launch_synchronization_outside_clocks(
    benchmark_module,
) -> None:
    """Host-launch samples have only clocks and operations in their interval."""
    workload = benchmark_module.build_default_profiling_workload_matrix()[0]
    events: list[str] = []
    ticks = iter(range(1, 10_000))

    def clock() -> int:
        events.append("clock")
        return next(ticks)

    binding = types.SimpleNamespace(
        enqueue=lambda: events.append("operation"),
        replay=lambda: events.append("replay"),
        reset=lambda: events.append("reset"),
        synchronize=lambda: events.append("synchronize"),
        validate_identities=lambda: events.append("validate"),
    )

    samples = benchmark_module._collect_profile_row(
        binding,
        workload,
        mode="prepared_uncaptured",
        source="host_launch",
        clock=clock,
    )

    assert [sample.replay_count for sample in samples] == [
        count
        for count in workload.replay_counts
        for _ in range(workload.sample_count)
    ]
    for index, event in enumerate(events):
        if event == "clock":
            assert (
                events[index + 1] == "operation"
                or events[index - 1] == "operation"
            )

def test_profile_artifact_publication_points_to_one_complete_generation(
    benchmark_module,
    tmp_path: Path,
) -> None:
    """Publish all four artifacts before atomically exposing their generation."""
    workloads = benchmark_module.build_default_profiling_workload_matrix()
    artifacts = {
        pair: benchmark_module.ProfilingArtifact(
            tuple(
                benchmark_module.UnavailableEvidence(
                    "unavailable", workload, "CUDA absent"
                )
                for workload in workloads
            )
        )
        for pair in benchmark_module.PROFILING_ARTIFACT_NAMES
    }

    benchmark_module._write_profile_artifacts(tmp_path, artifacts)

    profiling_root = tmp_path / "benchmarks" / "profiling"
    manifest = json.loads(
        (profiling_root / "manifest.json").read_text(encoding="utf-8")
    )
    assert set(manifest) == {
        f"{mode}/{method}"
        for mode, method in benchmark_module.PROFILING_ARTIFACT_NAMES
    }
    assert len({Path(value).parts[1] for value in manifest.values()}) == 1
    assert all(
        (profiling_root / value).is_file() for value in manifest.values()
    )
